@sig trait CapabilityAcquisition_Api {
  def id: Art.BridgeId
  def capability_snapshot_Id : Art.PortId
  def supplier_available_Id : Art.PortId
  def production_available_Id : Art.PortId
  def dispatch_available_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var supplier_available: Base_Types.Boolean = $

  def put_supplier_available(value : Base_Types.Boolean) : Unit = {
    Contract(
      Modifies(supplier_available),
      Ensures(
        supplier_available == value
      )
    )
    Spec {
      supplier_available = value
    }

    Art.putValue(supplier_available_Id, Base_Types.Boolean_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var production_available: Base_Types.Boolean = $

  def put_production_available(value : Base_Types.Boolean) : Unit = {
    Contract(
      Modifies(production_available),
      Ensures(
        production_available == value
      )
    )
    Spec {
      production_available = value
    }

    Art.putValue(production_available_Id, Base_Types.Boolean_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var dispatch_available: Base_Types.Boolean = $

  def put_dispatch_available(value : Base_Types.Boolean) : Unit = {
    Contract(
      Modifies(dispatch_available),
      Ensures(
        dispatch_available == value
      )
    )
    Spec {
      dispatch_available = value
    }

    Art.putValue(dispatch_available_Id, Base_Types.Boolean_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class CapabilityAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val capability_snapshot_Id : Art.PortId,
  val supplier_available_Id : Art.PortId,
  val production_available_Id : Art.PortId,
  val dispatch_available_Id : Art.PortId) extends CapabilityAcquisition_Api

@datatype class CapabilityAcquisition_Operational_Api (
  val id: Art.BridgeId,
  val capability_snapshot_Id : Art.PortId,
  val supplier_available_Id : Art.PortId,
  val production_available_Id : Art.PortId,
  val dispatch_available_Id : Art.PortId) extends CapabilityAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var capability_snapshot: Factory_Dispatch_Coordinator.CapabilitySnapshot = $

  def get_capability_snapshot() : Option[Factory_Dispatch_Coordinator.CapabilitySnapshot] = {
    Contract(
      Ensures(
        Res == Some(capability_snapshot)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.CapabilitySnapshot] = Art.getValue(capability_snapshot_Id) match {
      case Some(Factory_Dispatch_Coordinator.CapabilitySnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port capability_snapshot.  Expecting 'Factory_Dispatch_Coordinator.CapabilitySnapshot_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.CapabilitySnapshot]()
      case _ => None[Factory_Dispatch_Coordinator.CapabilitySnapshot]()
    }
    return value
  }
}
